let readingCelebrated=false;
function celebrateReading(percent){if(percent!==100||readingCelebrated||window.scrollY<10)return;readingCelebrated=true;const lion=document.getElementById('reading-lion');if(!lion)return;if(matchMedia('(prefers-reduced-motion: reduce)').matches){lion.classList.add('lion-complete');return;}const colors=['#dc3545','#2686c9','#e8ae19','#36a273','#9362c9','#ee6b31'];for(let i=0;i<18;i++){const spark=document.createElement('i');spark.className='reading-spark';spark.setAttribute('aria-hidden','true');const angle=(Math.PI*2*i)/18;const distance=22+(i%3)*8;spark.style.setProperty('--spark-x',Math.cos(angle)*distance+'px');spark.style.setProperty('--spark-y',Math.sin(angle)*distance+'px');spark.style.background=colors[i%colors.length];spark.style.animationDelay=(i%3)*45+'ms';lion.appendChild(spark);setTimeout(()=>spark.remove(),1600);}lion.classList.add('lion-complete');}
